package com.mavric.health.portal;
import java.util.*;
import java.time.Instant;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.identity.*;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.shared.*;
import com.mavric.health.scheduling.application.SchedulingService;
import com.mavric.health.scheduling.domain.Requests.Reserve;
import com.mavric.health.persistence.sqlserver.*;
import com.mavric.health.persistence.sqlserver.SqlServerPortalBalanceStoreTest.Fixture;
import static com.mavric.health.persistence.sqlserver.SqlServerPortalBalanceStoreTest.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Offline balance adapter/service, no ledger engine, runtime permission, HTTP or payment evidence. */
class PortalServiceBalanceSqlServerTest {
 final Fixture f=new Fixture();final Sql sql=mock(Sql.class);final Access access=mock(Access.class);final SchedulingService scheduling=mock(SchedulingService.class);final SqlServerPortalDocumentStore documents=mock(SqlServerPortalDocumentStore.class);final SqlServerPortalAppointmentStore appointments=mock(SqlServerPortalAppointmentStore.class);final SqlServerPortalPatientsStore patients=mock(SqlServerPortalPatientsStore.class);final PortalService service=new PortalService(documents,appointments,patients,f.store,sql,access,scheduling);
 PortalServiceBalanceSqlServerTest(){actor("PAC");when(access.tenantId()).thenReturn(TENANT);when(access.userId()).thenReturn(ACTOR);}
 void actor(String role){f.actor(role);doReturn(f.actor).when(access).actor();TraceContext.REQUEST.set(f.request);}
 @AfterEach void clean(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 @Test void pacResPortalFinanceThenOneSpPreservingNegativeAndZero(){for(String role:List.of("PAC","RES")){actor(role);f.amount=role.equals("PAC")?-12L:0L;assertEquals(Map.of("balanceMinor",f.amount,"currency","PEN"),service.balance(PATIENT));}verify(access,times(2)).roles("PAC","RES");verify(access,times(2)).module("PORTAL");verify(access,times(2)).module("FINANCE");verify(access,never()).link(anyString(),anyString());verify(f.executor,times(2)).execute(eq(SqlServerProcedure.PORTAL_BALANCE),any(),eq(PATIENT));verifyNoInteractions(sql,scheduling,documents,appointments,patients);}
 @Test void legacyGuardOrderPortalFinanceBeforeIdValidation(){assertEquals(400,assertThrows(ApiException.class,()->service.balance("bad")).status);var order=inOrder(access);order.verify(access).roles("PAC","RES");order.verify(access).module("PORTAL");order.verify(access).module("FINANCE");verify(access,never()).link(anyString(),anyString());verifyNoInteractions(f.executor,sql);}
 @Test void missingPortalAndFinanceStopBeforeLaterGuardsEvenWithInvalidId(){doThrow(new ApiException(401,"UNAUTHENTICATED","Safe")).when(access).roles("PAC","RES");assertEquals(401,assertThrows(ApiException.class,()->service.balance("bad")).status);verify(access,never()).module(anyString());doNothing().when(access).roles("PAC","RES");doThrow(new ApiException(403,"MODULE_NOT_INCLUDED","Safe")).when(access).module("PORTAL");assertEquals(403,assertThrows(ApiException.class,()->service.balance("bad")).status);verify(access,never()).module("FINANCE");doNothing().when(access).module("PORTAL");doThrow(new ApiException(403,"MODULE_NOT_INCLUDED","Safe")).when(access).module("FINANCE");assertEquals(403,assertThrows(ApiException.class,()->service.balance("bad")).status);verify(access,never()).actor();verifyNoInteractions(f.executor,sql);}
 @Test void missingRequestActorAndForgedHostFailWithoutAnyQuery(){TraceContext.REQUEST.remove();assertEquals(500,assertThrows(ApiException.class,()->service.balance(PATIENT)).status);actor("PAC");doThrow(new ApiException(401,"UNAUTHENTICATED","Safe")).when(access).actor();assertEquals(401,assertThrows(ApiException.class,()->service.balance(PATIENT)).status);actor("PAC");f.request.removeAttribute("health.actor");f.request.addHeader("X-Roles","PAC");assertEquals(403,assertThrows(ApiException.class,()->service.balance(PATIENT)).status);actor("PAC");f.request.setAttribute("health.tenant","bad");assertEquals(500,assertThrows(ApiException.class,()->service.balance(PATIENT)).status);actor("PAC");f.request.setAttribute("health.tenant",new TenantRef(OTHER,"Foreign","foreign","CLINIC","HUMAN","ACTIVE",List.of("PORTAL","FINANCE")));assertEquals(403,assertThrows(ApiException.class,()->service.balance(PATIENT)).status);verifyNoInteractions(f.executor,sql);}
 @Test void staffPlatformAndForgedRolesNeverGainBalanceAccess(){for(String role:List.of("ADM","REC","PRO","ASI","AUD","SAD","SOP")){actor(role);assertEquals(403,assertThrows(ApiException.class,()->service.balance(PATIENT)).status);}var a=new Actor(ACTOR,"Synthetic","synthetic@example.test",null,List.of("SAD"),"a".repeat(64));doReturn(a).when(access).actor();f.request.setAttribute("health.actor",a);f.request.removeAttribute("health.tenant");assertEquals(403,assertThrows(ApiException.class,()->service.balance(PATIENT)).status);verifyNoInteractions(f.executor,sql);}
 @Test void spBillingLinkPermissionAndInfrastructureErrorsNeverFallback(){for(int code:List.of(51001,51002,99999)){doThrow(new RuntimeException(new java.sql.SQLException("private driver canary",null,code))).when(f.executor).execute(any(),any(),any(Object[].class));var e=assertThrows(ApiException.class,()->service.balance(PATIENT));assertEquals(code==51001?403:code==51002?404:500,e.status);assertNull(e.getCause());assertFalse(e.toString().contains("canary"));}verify(f.executor,times(3)).execute(eq(SqlServerProcedure.PORTAL_BALANCE),any(),eq(PATIENT));verify(access,never()).link(anyString(),anyString());verifyNoInteractions(sql,scheduling);}
 @Test void mappingCommitAndOuterCancellationCannotReturnFakeBalance(){f.results.add(new SqlServerExecutor.Result(List.of(List.of(Map.of("balanceMinor",0,"currency","PEN"))),List.of()));assertEquals(500,assertThrows(ApiException.class,()->service.balance(PATIENT)).status);assertEquals("rollback",f.manager.events.getLast());f.manager.failCommit=true;assertEquals(500,assertThrows(ApiException.class,()->service.balance(PATIENT)).status);assertThrows(RuntimeException.class,()->f.manager.outer(()->{service.balance(PATIENT);throw new RuntimeException("cancel");}));assertEquals("rollback",f.manager.events.getLast());assertSame(f.actor,f.request.getAttribute("health.actor"));verifyNoInteractions(sql,scheduling);}
 @Test void sevenArgumentSelectionPreservesMigratedReadsAndSchedulingReserve(){var expected=List.<Map<String,Object>>of(Map.of("id",OTHER));when(documents.documents(f.request,PATIENT)).thenReturn(expected);when(appointments.appointments(f.request,PATIENT)).thenReturn(expected);when(patients.patients(f.request)).thenReturn(expected);var p=new Reserve(PATIENT,OTHER,OTHER,"H_FAMILY",Instant.parse("2026-11-05T00:00:00Z"),Instant.parse("2026-11-05T00:30:00Z"),"REQUESTED","Synthetic","");when(scheduling.reserve(p,"synthetic-key-001",true)).thenReturn(Map.of("id",OTHER));assertSame(expected,service.documents(PATIENT));assertSame(expected,service.appointments(PATIENT));assertSame(expected,service.patients());assertEquals(Map.of("id",OTHER),service.reserve(p,"synthetic-key-001"));verify(scheduling).reserve(p,"synthetic-key-001",true);verifyNoInteractions(f.executor,sql);}
 @Test void a40A41A42OverloadsKeepLegacyBalanceAndStoresUnchanged(){var expected=Map.<String,Object>of("balanceMinor",0L,"currency","PEN");when(sql.one(anyString(),any(Object[].class))).thenReturn(expected);for(PortalService selection:List.of(new PortalService(documents,sql,access,scheduling),new PortalService(documents,appointments,sql,access,scheduling),new PortalService(documents,appointments,patients,sql,access,scheduling))){assertSame(expected,selection.balance(PATIENT));}verify(access,times(3)).link(PATIENT,"BILLING");verify(sql,times(3)).one(anyString(),eq(TENANT),eq(PATIENT));verifyNoInteractions(f.executor,documents,appointments,patients);}
 @Test void minimalSpringStillSelectsLegacyConstructorWithoutDatasourceOrStore(){var expected=Map.<String,Object>of("balanceMinor",-1L,"currency","PEN");when(sql.one(anyString(),any(Object[].class))).thenReturn(expected);try(var context=new AnnotationConfigApplicationContext()){context.registerBean(Sql.class,()->sql);context.registerBean(Access.class,()->access);context.registerBean(SchedulingService.class,()->scheduling);context.registerBean(PortalService.class);context.refresh();assertSame(expected,context.getBean(PortalService.class).balance(PATIENT));verify(access).link(PATIENT,"BILLING");verify(sql).one(anyString(),eq(TENANT),eq(PATIENT));assertEquals(0,context.getBeanNamesForType(SqlServerPortalBalanceStore.class).length);assertEquals(0,context.getBeanNamesForType(javax.sql.DataSource.class).length);}verifyNoInteractions(f.executor,scheduling,documents,appointments,patients);}
}
